[Form]
public class METSalesOrderFinalizationWorkbench extends FormRun
{
    Map             headerMap;
    Map             lineMap;
    boolean         formInitialize;
    boolean         applyFilterValCtrl;
    boolean         selectAll;    
    METOrderTransactionType orderTransactionType;
    container       pickedLoadIds;
    container       nonPickedLoadIds;
    container       inCreditManagementShipmentIds;
    container       notInCreditManagementShipmentIds;
    boolean         hasUpdateRouteDialogRunOrCancelled;
    #Task

}

/// <summary>
/// Init method
/// </summary>
public void init()
{
    headerMap = new Map(Types::Int64, Types::String);
    lineMap = new Map(Types::String, Types::String);
    formInitialize = true;

    orderTransactionType = element.args().parmEnum();

    super();

    if (orderTransactionType == METOrderTransactionType::TransferOrder)
    {
        LineGrid_displaySalesStatus.visible(false);
        LineGrid_displayOrderExtractStatus.visible(false);
        ShipmentTabPage.visible(false);
        METSalesOrderShipmentLoadHeader_ds.object(fieldNum(METSalesOrderShipmentLoadHeader, PostMultiDocument)).visible(false);
        ApplyFilter.visible(false);
        LineGrid_OrderNum.label("@MET:TransferOrder");
        displayWarehouseInstructions.visible(false);
        displayCustomerInstructions.visible(false);
        METShipmentUpdateRoutesDialog.visible(false);
        METShipmentUpdateRoutesLineDialog.visible(false);
        displayIsOrderInCredManagement.visible(false);
    }
    else
    {
        LineGrid_displayTransferOrderExtractStatus.visible(false);
        LineGrid_displayTransferStatus.visible(false);
        ShipmentTabTransferOrder.visible(false);
        ApplyFilterTO.visible(false);
        LineGrid_OrderNum.label("@MET:SalesOrder");
        METShipmentUpdateRoutesDialogTransfer.visible(false);
        METShipmentUpdateRoutesLineDialogTransfer.visible(false);
    }
}

/// <summary>
/// method to show pick container fill up
/// </summary>
public void showPickContainerFillup()
{
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeaderLoc;
    Query query = METSalesOrderShipmentLoadHeader_ds.query();
    QueryRun queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        salesOrderShipmentLoadHeaderLoc = queryRun.get(tableNum(METSalesOrderShipmentLoadHeader));

        if (conFind(pickedLoadIds, salesOrderShipmentLoadHeaderLoc.LoadId) == 0 ||
            conFind(nonPickedLoadIds, salesOrderShipmentLoadHeaderLoc.LoadId) == 0)
        {
            if (salesOrderShipmentLoadHeaderLoc.displayLoadPickComplete())
            {
                pickedLoadIds += [salesOrderShipmentLoadHeaderLoc.LoadId];
            }
            else
            {
                nonPickedLoadIds += [salesOrderShipmentLoadHeaderLoc.LoadId];
            }
        }

        if (salesOrderShipmentLoadHeaderLoc.TransactionType == METOrderTransactionType::SalesOrder)
        {
            if (conFind(inCreditManagementShipmentIds, salesOrderShipmentLoadHeaderLoc.ShipmentId) == 0 ||
                conFind(notInCreditManagementShipmentIds, salesOrderShipmentLoadHeaderLoc.ShipmentId) == 0)
            {
                if (salesOrderShipmentLoadHeaderLoc.displayIsOrderInCredManagement())
                {
                    inCreditManagementShipmentIds += [salesOrderShipmentLoadHeaderLoc.ShipmentId];
                }
                else
                {
                    notInCreditManagementShipmentIds += [salesOrderShipmentLoadHeaderLoc.ShipmentId];
                }
            }
        }
    }
}

/// <summary>
/// Method to reset map and the mark on grid
/// </summary>
/// <param name = "_map">Map reference</param>
public void cleanupMarkMap(Map      _map, boolean _isHeaderMap = false)
{
    Set             setRec;
    MapEnumerator   mapEnumerator = _map.getEnumerator();
    SetEnumerator   setEnumerator;

    if (_isHeaderMap)
    {
        setRec = new Set(Types::Int64);
    }
    else
    {
        setRec = new Set(Types::String);
    }

    while (mapEnumerator.moveNext())
    {
        setRec.add(mapEnumerator.currentKey());
    }

    setEnumerator = setRec.getEnumerator();

    while (setEnumerator.moveNext())
    {
        if (_map.exists(setEnumerator.current()))
        {
            _map.remove(setEnumerator.current());
        }
    }

    METSalesOrderShipmentLoadLines_ds.executeQuery();
}

