/// <summary>
/// This is a method to reset the filters applied on dialog and also reset the map and marks on grid when user clicks on 'Apply Filter' button on dialog.
/// </summary>
public void resetOnDialogApplyFilter()
{
    this.cleanupMarkMap(headerMap, true);
    this.cleanupMarkMap(lineMap);

    QueryBuildDataSource qbdsLine =
    METSalesOrderShipmentLoadLines_ds.queryBuildDataSource();

    qbdsLine.clearRanges();
    SysQuery::findOrCreateRange(qbdsLine,
    fieldNum(METSalesOrderShipmentLoadLines, RecId)).value(queryValue(0));

    METSalesOrderShipmentLoadLines_ds.executeQuery();
}

