/// <summary>
/// Execute method for datasource
/// </summary>
public void executeQuery()
{
    Map tempMap = new Map(Types::Int64, Types::String);
    if (formInitialize)
    {
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, RecId)).value(queryValue(0)); // Need to open form blank and data should fetched based on the filters selected
    }

    ShowShipmentPick.enabled(!formInitialize);
    ShowLoadPick.enabled(!formInitialize);
    ShowInCreditManagement.enabled(!formInitialize);

    if (pickedLoadIds == conNull() || nonPickedLoadIds == conNull())
    {
        element.showPickContainerFillup();
    }

    METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource().clearRange(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId));
    METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource().clearRange(fieldNum(METSalesOrderShipmentLoadHeader, LoadId));

    //Show Shipment Pick Filter
    if (ShowShipmentPick.selection() == METShowAll::No)
    {
        //SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId)).value(queryNotValueCon_W(pickedSOShipmentIds));
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Shipmentpickcomplete)).value(queryValue(NoYes::No));
    }
    else if (ShowShipmentPick.selection() == METShowAll::Yes)
    {
        //SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId)).value(queryNotValueCon_W(nonPickedSOShipmentIds));
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Shipmentpickcomplete)).value(queryValue(NoYes::Yes));
    }

    //Show Load Pick Filter
    if (ShowLoadPick.selection() == METShowAll::No)
    {
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, LoadId)).value(queryNotValueCon_W(pickedLoadIds));
    }
    else if (ShowLoadPick.selection() == METShowAll::Yes)
    {
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, LoadId)).value(queryNotValueCon_W(nonPickedLoadIds));
    }

    //Show In Credit Management Filter
    if (ShowInCreditManagement.selection() == METShowAll::No)
    {
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId)).value(queryNotValueCon_W(inCreditManagementShipmentIds));
    }
    else if (ShowInCreditManagement.selection() == METShowAll::Yes)
    {
        SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId)).value(queryNotValueCon_W(NotInCreditManagementShipmentIds));
    }

    if (!selectAll)
    {
        tempMap = headerMap;
        headerMap = new Map(Types::Int64, Types::String);
    }
    super();            
}

/// <summary>
/// This is an edit method
/// </summary>
/// <param name = "_set">Set</param>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader reference</param>
/// <param name = "_mark">mark reference</param>
/// <returns>EditValue</returns>
[SysClientCacheDataMethodAttribute(true)]
public edit NoYes editMarkHeaderMap(boolean _set, METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader, NoYes _mark)
{
    if (!_set)
    {
        return headerMap.exists(_metSalesOrderShipmentLoadHeader.RecId);
    }

    boolean mapChanged = false;
    if (_mark)
    {
        if (!headerMap.exists(_metSalesOrderShipmentLoadHeader.RecId))
        {
            headerMap.insert(_metSalesOrderShipmentLoadHeader.RecId, _metSalesOrderShipmentLoadHeader.ShipmentId);
            mapChanged = true;
        }
    }
    else
    {
        if (headerMap.exists(_metSalesOrderShipmentLoadHeader.RecId))
        {
            headerMap.remove(_metSalesOrderShipmentLoadHeader.RecId);
            mapChanged = true;
        }
    }

    if (mapChanged)
    {
        applyFilterValCtrl = true;
        METSalesOrderShipmentLoadLines_ds.executeQuery();
        applyFilterValCtrl = false;
    }

    return headerMap.exists(_metSalesOrderShipmentLoadHeader.RecId);
}

