/// Datasource init method
/// </summary>
public void init()
{
    super();

    SysQuery::findOrCreateRange(METSalesOrderShipmentLoadHeader_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, TransactionType)).value(queryValue(orderTransactionType)); 
}

/// <summary>
/// Selection changed method for shipment and load mark if the status is open only
/// </summary>
public void selectionChanged()
{
    METSalesOrderShipmentLoadHeader     salesOrderShipmentLoadHeaderLoc;
    super();

    boolean canReviewSelection = true;

    MapEnumerator       headerMapEnumerator = headerMap.getEnumerator();

    while (headerMapEnumerator.moveNext())
    {
        select firstonly ShipmentStatus from salesOrderShipmentLoadHeaderLoc
            where salesOrderShipmentLoadHeaderLoc.RecId == headerMapEnumerator.currentKey();

        canReviewSelection = canReviewSelection && salesOrderShipmentLoadHeaderLoc.ShipmentStatus == MetShipmentStatus::Open;
    }

    METShipmentUpdateRoutesDialog.enabled(canReviewSelection);
    element.cleanupMarkMap(lineMap);
}

/// <summary>
/// display method to show the count of marked records
/// </summary>
display int dislayMarkedRecords()
{
    return headerMap.elements();
}

[FormObservable]
display NoYes dislayLoadPick(METSalesOrderShipmentLoadHeader    _metSalesOrderShipmentLoadHeader)
{

    return conFind(pickedLoadIds, _metSalesOrderShipmentLoadHeader.LoadId) == 0
                                                                                    ? NoYes::No
                                                                                    : NoYes::Yes;
}

[FormObservable]
display CredManUsedInCreditManagement dislayIsCreditManagement(METSalesOrderShipmentLoadHeader    _metSalesOrderShipmentLoadHeader)
{
    return conFind(inCreditManagementShipmentIds, _metSalesOrderShipmentLoadHeader.ShipmentId) == 0
                                                                                    ? NoYes::No
                                                                                    : NoYes::Yes;
}

