/// <summary>
/// Data source init method
/// </summary>
public void init()
{
    super();

    METSalesOrderShipmentLoadLines_ds.queryBuildDataSource().addGroupByField(fieldNum(METSalesOrderShipmentLoadLines, OrderNum));
    METSalesOrderShipmentLoadLines_ds.queryBuildDataSource().addGroupByField(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));

    if (orderTransactionType == METOrderTransactionType::SalesOrder)
    {
        QueryBuildDataSource        qbdsSalesLine = METSalesOrderShipmentLoadLines_ds.queryBuildDataSource().addDataSource(tableNum(SalesLine));

        qbdsSalesLine.relations(false);
        qbdsSalesLine.addLink(fieldNum(METSalesOrderShipmentLoadLines, OrderNum), fieldNum(SalesLine, SalesId));
        qbdsSalesLine.addLink(fieldNum(METSalesOrderShipmentLoadLines, LineNum), fieldNum(SalesLine, LineNum));

        qbdsSalesLine.joinMode(JoinMode::ExistsJoin);

        QueryBuildDataSource        qbdsWmsOrderTrans = qbdsSalesLine.addDataSource(tableNum(WMSOrderTrans));

        qbdsWmsOrderTrans.relations(false);
        qbdsWmsOrderTrans.addLink(fieldNum(SalesLine, InventTransId), fieldNum(WMSOrderTrans, inventTransId));
        qbdsWmsOrderTrans.joinMode(JoinMode::ExistsJoin);
    }
}

/// <summary>
/// This is an edit method
/// </summary>
/// <param name = "_set">Set</param>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines reference</param>
/// <param name = "_mark">mark reference</param>
/// <returns>EditValue</returns>
[SysClientCacheDataMethodAttribute(true)]
public edit NoYes editMarkLineMap(boolean _set, METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines, NoYes _mark)
{
    if (_set)
    {
        if (!_mark)
        {
            if (lineMap.exists(_metSalesOrderShipmentLoadLines.OrderNum))
            {
                lineMap.remove(_metSalesOrderShipmentLoadLines.OrderNum);
            }
        }
        else
        {
            lineMap.insert(_metSalesOrderShipmentLoadLines.OrderNum, _metSalesOrderShipmentLoadLines.ShipmentId);
        }
    }
    return lineMap.exists(_metSalesOrderShipmentLoadLines.OrderNum);
}

/// <summary>
/// Execute method for  datasource
/// </summary>
public void executeQuery()
{
    if (formInitialize)
    {
        this.clearLineDatasourceData();
    }

    if (applyFilterValCtrl)
    {
        if (headerMap.pack() != conNull())
        {
            this.addFilterHeaderShipmentId(headerMap.pack());
        }
        else
        {
            this.clearLineDatasourceData();
        }
    }

    super();
}

/// <summary>
/// Blank datasource data
/// </summary>
public void clearLineDatasourceData()
{
    SysQuery::findOrCreateRange(METSalesOrderShipmentLoadLines_ds.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadLines, RecId)).value(queryValue(0));
}

/// <summary>
/// Add filter for header shipment ID
/// </summary>
/// <param name = "_conHeaderData">Header data</param>
public void addFilterHeaderShipmentId(container _conHeaderData)
{
    QueryBuildDataSource qbds = METSalesOrderShipmentLoadLines_ds.queryBuildDataSource();
    qbds.clearRanges();
    qbds.addOrderByField(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));

    // Collect all shipment IDs in one pass
    container shipmentIds = conNull();
    for (int i = 1; i <= conLen(_conHeaderData); i++)
    {
        METSalesOrderShipmentLoadHeader header = METSalesOrderShipmentLoadHeader::findByRecId(conPeek(_conHeaderData, i));
        shipmentIds += [header.ShipmentId];
    }
    // Add all ranges in one pass
    for (int i = 1; i <= conLen(shipmentIds); i++)
    {
        qbds.addRange(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId)).value(queryValue(conPeek(shipmentIds, i)));
    }
    qbds.addRange(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId)).status(RangeStatus::Hidden);
}

/// <summary>
/// Jump ref method for order num field
/// </summary>
public void jumpRef()
{
    SalesTable      salesTable;
    InventTransferTable inventTransferTable;
    MenuFunction    menuFunction;
    Args            args = new Args();

    if (orderTransactionType == METOrderTransactionType::SalesOrder)
    {
        select firstonly salesTable
            where salesTable.SalesId == METSalesOrderShipmentLoadLines.OrderNum;

        args.record(salesTable);
        args.caller(element);
        menuFunction = new MenuFunction(MenuItemDisplayStr(SalesTable), MenuItemType::Display);
    }
    else
    {
        select firstonly inventTransferTable
            where inventTransferTable.TransferId == METSalesOrderShipmentLoadLines.OrderNum;

        args.record(inventTransferTable);
        args.caller(element);
        menuFunction = new MenuFunction(MenuItemDisplayStr(InventTransferOrder), MenuItemType::Display);
    }

    menuFunction.run(args);
}

/// <summary>
/// Select all records in the grid
/// </summary>
public void clicked()
{
    METSalesOrderShipmentLoadHeader     salesOrderShipmentLoadHeaderLoc = METSalesOrderShipmentLoadHeader_ds.getFirst() ? METSalesOrderShipmentLoadHeader_ds.getFirst() : METSalesOrderShipmentLoadHeader_ds.cursor();
    boolean                             mapChanged = false;
    while (salesOrderShipmentLoadHeaderLoc)
    {
        headerMap.insert(salesOrderShipmentLoadHeaderLoc.RecId, salesOrderShipmentLoadHeaderLoc.ShipmentId);
        mapChanged = true;
        selectAll = true;
        salesOrderShipmentLoadHeaderLoc = METSalesOrderShipmentLoadHeader_ds.getNext();
    }

    if (mapChanged)
    {
        applyFilterValCtrl = true;
        METSalesOrderShipmentLoadLines_ds.executeQuery();
        applyFilterValCtrl = false;

        element.task(#taskRefresh);
    }
    super();
    selectAll = false;
}

/// <summary>
/// Select all records in the grid
/// </summary>
public void clicked()
{
    METSalesOrderShipmentLoadHeader     salesOrderShipmentLoadHeaderLoc = METSalesOrderShipmentLoadHeader_ds.getFirst() ? METSalesOrderShipmentLoadHeader_ds.getFirst() : METSalesOrderShipmentLoadHeader_ds.cursor();
    boolean                             mapChanged = false;

    if (headerMap.elements())
    {
        while (salesOrderShipmentLoadHeaderLoc)
        {
            if (headerMap.exists(salesOrderShipmentLoadHeaderLoc.RecId))
            {
                headerMap.remove(salesOrderShipmentLoadHeaderLoc.RecId);
                mapChanged = true;
            }

            salesOrderShipmentLoadHeaderLoc = METSalesOrderShipmentLoadHeader_ds.getNext();
        }

        if (mapChanged)
        {
            applyFilterValCtrl = true;
            METSalesOrderShipmentLoadLines_ds.executeQuery();
            applyFilterValCtrl = false;

            element.task(#taskRefresh);
        }
    }
    super();
}

