/// <summary>
/// Clicked method to refresh the routes
/// </summary>
public void clicked()
{
    super();

    // Similar check with the same varaible in done for 'Update Route' option on the Lines, considering at any given point either of one, header or line
    // option will be used.
    if (hasUpdateRouteDialogRunOrCancelled)
    {
        METSalesOrderShipmentLoadHeader_ds.research(true);
        METSalesOrderShipmentLoadLines_ds.research(true);
        METSalesOrderShipmentLoadHeader_ds.refresh();
        METSalesOrderShipmentLoadLines_ds.refresh();

        //Since it is asked to clear the Marked records on the header upon 
        //'Update Route' option, we are clearing the maps, so that marked records are not seen as marked anymore.
        //Therefore the ranges on lines datasources must be cleared as in clearLineDatasourceData method.
        //If its asked to keep the marked records even after update route then we can remove the below call from here and marked lines will still be marked after route update.
        element.resetLineDSOnUpdateRoute();
    }
}

