/// <summary>
/// Opens the WMSPickingRegistration form in Grid view and passes the
/// appropriate source record based on the originating menu item.
/// </summary>
/// <remarks>
/// This method inspects the caller menu item to determine whether the user
/// launched the action from the Sales Order Finalization Workbench or the
/// Transfer Order Finalization Workbench. Based on the source, the method
/// retrieves the corresponding SalesTable or InventTransferTable record and
/// passes it through Args to the WMSPickingRegistration form.
///
/// The form is explicitly opened in Grid view using FormViewOption::Grid,
/// and the current form is set as the caller to preserve navigation context.
/// </remarks>
public void clicked()
{
    super();

    Args args = new Args();

    if (this.formRun().args().menuItemName() == menuItemDisplayStr(METSalesOrderFinalizationWorkbench))
    {
        args.record(SalesTable::find(METSalesOrderShipmentLoadLines.OrderNum));
    }
    else if (this.formRun().args().menuItemName() == menuItemDisplayStr(METTransferOrderFinalizationWorkbench))
    {
        args.record(InventTransferTable::find(METSalesOrderShipmentLoadLines.OrderNum));
    }

    args.caller(this);
    args.menuItemName(this.formRun().args().menuItemName());
    args.formViewOption(FormViewOption::Grid); // Opens the form with Grid as default View

    new MenuFunction(menuitemDisplayStr(WMSPickingRegistration), MenuItemType::Display).run(args);
}
